var p1=sjs.match(/var t2=(\d+),a8=(\d+),r=(\d+)/);
var t2=p1?parseInt(p1[1],10):29241,a8=p1?parseInt(p1[2],10):28564,r=p1?parseInt(p1[3],10):38070;
var p2=sjs.match(/s9<(\d+);s9\+\+/);
var rounds=p2?parseInt(p2[1],10):32393;
var s=enc(String(key));
var u4=7,i;
for(i=0;i<s.length;i+=2){
u4=((u4*31)^(s.charCodeAt(i)*t2))>>>0;
if(i+1<s.length){u4=((u4*31)^(s.charCodeAt(i+1)*a8))>>>0;}
u4=(u4+t.charCodeAt((i>>1)%t.length)+r)>>>0;
}
var ts=Math.floor(Date.now()/1000);
u4=(u4^ts)>>>0;
for(i=0;i<rounds;i++){u4=((u4<<5)+u4)>>>0;}
